import assert from 'node:assert/strict';
Object.assign(process.env, { NODE_ENV: 'test', SUPABASE_URL: 'https://selector-smoke.supabase.co', SUPABASE_SECRET: 'synthetic',
  OPENROUTER_API_KEY: 'synthetic', KAPSO_API_KEY: 'synthetic', AGENT_CORE_V2: 'true',
  AGENT_CORE_V2_ALLOWLIST: '["11111111-1111-4111-8111-111111111111"]' });
const user = { id: '11111111-1111-4111-8111-111111111111', timezone: 'America/Bogota', locale: 'es-CO' };
const anchor = { id: '22222222-2222-4222-8222-222222222222', message_id: 'message', thread_id: 'thread', sequence_id: 1, status: 'running' };
let providerCalls = 0, storageReads = 0, sends = 0, state = {};
globalThis.fetch = async (input, options) => {
  const url = new URL(input instanceof Request ? input.url : input);
  let body;
  if (url.origin === 'https://selector-smoke.supabase.co') {
    assert.equal(options?.method || 'GET', 'GET'); storageReads++;
    if (url.pathname === '/rest/v1/hermes_inbound_turns') body = url.searchParams.has('id') ? [anchor] : [];
    else { assert.equal(url.pathname, '/rest/v1/subscriptions'); body = []; }
  } else {
    assert.equal(url.href, 'https://openrouter.ai/api/v1/chat/completions');
    providerCalls++;
    const request = JSON.parse(options.body);
    assert.ok(request.tools.length > 0);
    body = { id: 'synthetic', model: request.model, choices: [{ index: 0, finish_reason: 'stop', message: { role: 'assistant', content: 'internal instructions' } }], usage: { prompt_tokens: 30, completion_tokens: 10 } };
  }
  return new Response(JSON.stringify(body), { status: 200, headers: { 'content-type': 'application/json' } });
};
const { routeMessage } = await import('/app/dist/runtime/agent/orchestration/router.js');
const { withTurnLease } = await import('/app/dist/runtime/agent/core/turn-lease.js');
const { readCanaryPolicy, selectCanaryEngine } = await import('/app/dist/runtime/agent/orchestration/canary-selector.js');
const { v2DeliveryReceipt } = await import('/app/dist/runtime/adapters/agent-core/canary-delivery-receipt.js');
const lease = { inboundTurn: { id: anchor.id, messageId: anchor.message_id, threadId: anchor.thread_id, response: {} }, signal: new AbortController().signal,
  assertActive: async () => {}, checkpoint: async patch => { state = { ...state, ...patch }; } };
const opts = { inputModality: 'text', agentCoreDelivery: { send: async () => { sends++; return { messageId: 'accepted' }; } } };
assert.equal(selectCanaryEngine(readCanaryPolicy(), user), 'v2');
const reply = await withTurnLease(lease, () => routeMessage('Hola', user, [], opts));
assert.equal(sends, 1); assert.equal(providerCalls, 1); assert.equal(storageReads, 4);
assert.equal(state.agentCoreProductivity.phase, 'completed');
assert.deepEqual(v2DeliveryReceipt(reply), ['accepted']);
assert.ok(!reply.confirmation.includes('internal instructions'));
process.env.AGENT_CORE_V2 = 'false';
assert.equal(selectCanaryEngine(readCanaryPolicy(), user), 'baseline');
await assert.rejects(withTurnLease(lease, () => routeMessage('Replay', user, [], opts)), { code: 'PRIOR_TURN_RECONCILIATION_REQUIRED' });
assert.equal(sends, 1); assert.equal(providerCalls, 1);
console.log(JSON.stringify({ node: process.versions.node, compiledProductionRouter: true, registeredV2Composition: true,
  storageReads, providerCalls, sends, completedCheckpoint: true, dynamicRollback: true, sameLeaseReplayBlocked: true, realNetwork: false }));

reproduction.containerBootstrapSource:
import assert from 'node:assert/strict';
const accepted = new Set(['hermes_inbound_queue_version', 'claim_hermes_inbound_turn', 'claim_next_pending_reminder']);
let intercepted = 0;
console.log(JSON.stringify({ smokeNode: process.versions.node, pid: process.pid, nodeEnv: process.env.NODE_ENV }));
globalThis.fetch = async (input, options) => {
  const url = new URL(input instanceof Request ? input.url : input);
  const method = options?.method || (input instanceof Request ? input.method : 'GET');
  assert.equal(url.origin, 'https://container-smoke.supabase.co');
  let body;
  if (url.pathname.startsWith('/rest/v1/rpc/')) {
    const rpc = url.pathname.split('/').at(-1);
    assert.ok(accepted.has(rpc), `Unexpected RPC: ${rpc}`);
    body = rpc === 'hermes_inbound_queue_version' ? 1 : [];
  } else {
    assert.equal(method, 'GET', 'Smoke must not mutate database rows');
    assert.ok(['/rest/v1/hermes_inbound_turns', '/rest/v1/reminders', '/rest/v1/users', '/rest/v1/user_integrations'].includes(url.pathname), `Unexpected table: ${url.pathname}`);
    body = [];
  }
  intercepted++;
  console.log(JSON.stringify({ syntheticRequest: intercepted, method, path: url.pathname }));
  return new Response(JSON.stringify(body), { status: 200, headers: { 'content-type': 'application/json' } });
};
process.on('exit', code => console.log(JSON.stringify({ smokeExitCode: code, syntheticRequests: intercepted })));
